var a=`0054-cesnecka`;var i=`world-0054`;var n=`CZ`;var s=`eastern-europe`;var r=4;var o=32;var d={en:`Česnečka`,ua:`Часниковий суп`};var u={en:`A classic dish from Czechia, featuring potato, bay leaf, garlic, rye bread. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Чехія. Основні складники: картопля, лавровий лист, часник, житній хліб. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 18 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 18 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:18,i:[[`potato`,340,`g`],[`water`,1200,`ml`],[`caraway-seeds`,3,`g`],[`bay-leaf`,1,`leaf`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 5 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 5 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:5,i:[[`garlic`,7,`clove`],[`unsalted-butter`,35,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`dried-marjoram`,4,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Toast these ingredients over medium heat for about 6 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 6 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:6,i:[[`rye-bread`,160,`g`]]}];var l={slug:a,id:i,country:`CZ`,region:s,servings:4,minutes:32,title:d,text:u,steps:g};export{n as country,l as default,i as id,o as minutes,s as region,r as servings,a as slug,g as steps,u as text,d as title};